### Folds




::: {.cell tbl-cap='Folds for Weight and Reproduction for each model.'}

```{.r .cell-code}
No_round <- 1

f_count_fold <- function(df_predobs_Weight, df_predobs_Reproduction, No_round) {

  df_predobs_Weight <- df_predobs_Weight  |>
  mutate(
    Ratio_predobs = predict.endpoint / Weight_obs,
    Residuals = predict.endpoint - Weight_obs
  )
  df_predobs_Reproduction <- df_predobs_Reproduction  |>
  mutate(
    Ratio_predobs = predict.endpoint / Reproduction_obs,
    Residuals = predict.endpoint - Reproduction_obs
  )

  Weight_count_fold2 <- round(length(subset(df_predobs_Weight, Ratio_predobs >= 0.5 & Ratio_predobs <= 2)$Weight_obs) / length(df_predobs_Weight$Weight_obs) * 100, No_round)

  Weight_count_fold5 <- round(length(subset(df_predobs_Weight, Ratio_predobs >= 0.2 & Ratio_predobs <= 5)$Weight_obs) / length(df_predobs_Weight$Weight_obs) * 100, No_round)

  Repro_count_fold2 <- round(length(subset(df_predobs_Reproduction, Ratio_predobs >= 0.5 & Ratio_predobs <= 2)$Reproduction_obs) / length(df_predobs_Reproduction$Reproduction_obs) * 100, No_round)

  Repro_count_fold5 <- round(length(subset(df_predobs_Reproduction, Ratio_predobs >= 0.2 & Ratio_predobs <= 5)$Reproduction_obs) / length(df_predobs_Reproduction$Reproduction_obs) * 100, No_round)

  df_predobs_Reproduction_0 <- df_predobs_Reproduction |>
    filter(Reproduction_obs > 0) 

  Repro0_count_fold2 <- round(length(subset(df_predobs_Reproduction_0, Ratio_predobs >= 0.5 & Ratio_predobs <= 2)$Reproduction_obs) / length(df_predobs_Reproduction_0$Reproduction_obs) * 100, No_round)

  Repro0_count_fold5 <- round(length(subset(df_predobs_Reproduction_0, Ratio_predobs >= 0.2 & Ratio_predobs <= 5)$Reproduction_obs) / length(df_predobs_Reproduction_0$Reproduction_obs) * 100, No_round)

  df_fold <- data.frame(
    Endpoint = c("Weight", "Reproduction", "Observed reproduction above 0"),
    '% of predictions in fold 2' = c(Weight_count_fold2, Repro_count_fold2, Repro0_count_fold2),
    '% of predictions in fold 5' = c(Weight_count_fold5, Repro_count_fold5, Repro0_count_fold5),
  check.names = FALSE
  )

  return(df_fold)

}

list_weight <- mget(paste0("df_predobs_Weight_", list_models))
list_repro  <- mget(paste0("df_predobs_Reproduction_", list_models))

