### RMSE per experiment




::: {.cell tbl-cap='RMSE for Weight and Reproduction per experiment for each model.'}

```{.r .cell-code}
f_RMSE_experiment <- function(df_predobs_Weight, df_predobs_Reproduction){

  df_rmse_W <- df_predobs_Weight %>%
    group_by(ID_experiment) %>%
    summarise(
      RMSE_Weight = sqrt(mean((predict.endpoint - Weight_obs)^2, na.rm = TRUE))
    )

  df_rmse_R <- df_predobs_Reproduction %>%
    group_by(ID_experiment) %>%
    summarise(
      RMSE_Reproduction = sqrt(mean((predict.endpoint - Reproduction_obs)^2, na.rm = TRUE))
    )

  df_rmse <- left_join(df_rmse_W, df_rmse_R)

  return(df_rmse)
}


df_rmse <- purrr::map2_dfr(
  list_weight,
  list_repro,
  f_RMSE_experiment,
  .id = "Model"
)

df_rmse <- df_rmse %>%
  dplyr::mutate(Model = str_remove(Model, "df_predobs_(Weight|Reproduction)_")) %>%
  pivot_longer(
    cols = starts_with("RMSE"),
    names_to = "Metric",
    values_to = "RMSE"
  )

df_rmse |>
  pivot_wider(
    names_from = Metric,
    values_from = RMSE
  ) |> 
  datatable(
  options = list(
    dom = 't',
    pageLength = nrow(df_rmse),
    autoWidth = TRUE,
    columnDefs = list(
      list(className = 'dt-left', targets = "_all")
    )
  ),
  class = "hover"
)
