ID_exp_plot_1 <- unique(df_rmse$ID_experiment)[1:6]
ID_exp_plot_2 <- unique(df_rmse$ID_experiment)[7:12]

ylim_metric <- df_rmse |>
  group_by(Metric) |>
  summarise(
    ymin = min(RMSE, na.rm = TRUE),
    ymax = max(RMSE, na.rm = TRUE),
    .groups = "drop"
  )

make_plot <- function(data, ids, metric_name) {

  lims <- ylim_metric |>
    filter(Metric == metric_name)

  ggplot(
    subset(data, ID_experiment %in% ids & Metric == metric_name),
    aes(
      x = Model,
      y = RMSE,
      color = Model
    )
  ) +
    geom_point(size = 2) +
    facet_grid(
      . ~ ID_experiment
    ) +
    coord_cartesian(
      ylim = c(lims$ymin, lims$ymax)
    ) +
    scale_color_manual(
      name = "Models",
      values = c(Nord_aurora, Nord_frost)
    ) +
    theme_bw() +
    theme(
      axis.text.x = element_text(angle = 45, hjust = 1, size = 8),
      strip.text = element_text(size = 8)
    ) +
    labs(
      x = "Model",
      y = "RMSE"
    )
}

p1_metric1 <- make_plot(df_rmse, ID_exp_plot_1, unique(df_rmse$Metric)[1]) +
  labs(title = "RMSE Weight") +
  theme(
    axis.title.x = element_blank()
  )
p2_metric1 <- make_plot(df_rmse, ID_exp_plot_2, unique(df_rmse$Metric)[1])

p1_metric2 <- make_plot(df_rmse, ID_exp_plot_1, unique(df_rmse$Metric)[2]) +
  labs(title = "RMSE Reproduction") +
  theme(
    axis.title.x = element_blank()
  )
p2_metric2 <- make_plot(df_rmse, ID_exp_plot_2, unique(df_rmse$Metric)[2])

p <- (
  p1_metric1 / p2_metric1 /
  p1_metric2 / p2_metric2
) +
  plot_layout(guides = "collect")

p
